const savedSuppliers=new Set(read('vv-saved-suppliers',[]));
const shoppingItems=['Fresh tomatoes','Red onions','Fresh potatoes','Sona masoori rice'];
let shoppingList=read('vv-shopping-list',[]);
const saveExtras=()=>{try{localStorage.setItem('vv-saved-suppliers',JSON.stringify([...savedSuppliers]));localStorage.setItem('vv-shopping-list',JSON.stringify(shoppingList))}catch{toast('Browser storage is unavailable; changes last for this visit.')}};
const extras=document.createElement('section');extras.className='market-extras';extras.innerHTML=`<div class="quick-panel"><span class="eyebrow">A QUICK START</span><h2>What does your stall need?</h2><p class="muted">Jump straight to your everyday essentials.</p><div class="quick-products">${[['🍅','Fresh tomatoes','tomatoes'],['🌾','Sona masoori rice','rice'],['🛢️','Sunflower oil','sunflower'],['🥛','Fresh milk','milk'],['📦','Paper cups (100 pcs)','cups'],['🧼','Dishwashing liquid','dishwashing']].map(([icon,name,query])=>`<button data-quick-search="${query}"><span aria-hidden="true">${icon}</span><span>${name}</span><span aria-hidden="true">↗</span></button>`).join('')}</div></div><div class="checklist-panel"><span class="eyebrow">PLAN YOUR NEXT RESTOCK</span><h2>Your shopping checklist</h2><p class="muted">Tick what you need, then search the market.</p><div class="shopping-checklist">${shoppingItems.map((name,i)=>`<label><input type="checkbox" data-shopping-item="${i}" ${shoppingList.includes(name)?'checked':''}><span>${name}</span></label>`).join('')}</div><div class="checklist-footer"><span id="shoppingCount"></span><button id="clearChecklist">Clear list</button></div></div>`;
$('#categories').after(extras);
extras.onclick=e=>{const button=e.target.closest('[data-quick-search]');if(!button)return;category='All supplies';document.querySelector('[data-cat="All supplies"]').click();$('#search').value=button.dataset.quickSearch;render();$('#cards').scrollIntoView({behavior:'smooth',block:'start'})};
function updateShoppingCount(){$('#shoppingCount').textContent=`${shoppingList.length} items to restock`}
extras.onchange=e=>{if(e.target.dataset.shoppingItem===undefined)return;const name=shoppingItems[Number(e.target.dataset.shoppingItem)];shoppingList=e.target.checked?[...new Set([...shoppingList,name])]:shoppingList.filter(n=>n!==name);saveExtras();updateShoppingCount()};
$('#clearChecklist').onclick=()=>{shoppingList=[];document.querySelectorAll('[data-shopping-item]').forEach(input=>input.checked=false);saveExtras();updateShoppingCount()};updateShoppingCount();
const profileContainer=$('#wholesalerProfiles');
profileContainer.querySelectorAll('.wholesaler-card').forEach((card,i)=>{const button=document.createElement('button');button.className='save-supplier';button.dataset.saveSupplier=i;button.type='button';card.querySelector('.orderbtn').before(button)});
const filterBar=document.createElement('div');filterBar.className='supplier-filter';filterBar.innerHTML='<button id="allWholesalers" class="selected" aria-pressed="true">All wholesalers</button><button id="savedWholesalers" aria-pressed="false">Saved wholesalers <span id="savedSupplierCount"></span></button>';profileContainer.before(filterBar);
const noSaved=document.createElement('p');noSaved.className='muted';noSaved.textContent='No saved wholesalers yet. Tap Save wholesaler on a profile to keep it handy.';noSaved.hidden=true;profileContainer.after(noSaved);let savedOnly=false;
function updateSavedSuppliers(){profileContainer.querySelectorAll('.wholesaler-card').forEach((card,i)=>{const saved=savedSuppliers.has(wholesalers[i].name);card.hidden=savedOnly&&!saved;const button=card.querySelector('[data-save-supplier]');button.textContent=saved?'♥ Saved wholesaler':'♡ Save wholesaler';button.setAttribute('aria-pressed',String(saved))});$('#savedSupplierCount').textContent=`(${savedSuppliers.size})`;noSaved.hidden=!savedOnly||savedSuppliers.size>0;$('#allWholesalers').classList.toggle('selected',!savedOnly);$('#savedWholesalers').classList.toggle('selected',savedOnly);$('#allWholesalers').setAttribute('aria-pressed',String(!savedOnly));$('#savedWholesalers').setAttribute('aria-pressed',String(savedOnly))}
profileContainer.addEventListener('click',e=>{const button=e.target.closest('[data-save-supplier]');if(!button)return;const name=wholesalers[Number(button.dataset.saveSupplier)].name;if(savedSuppliers.has(name))savedSuppliers.delete(name);else savedSuppliers.add(name);saveExtras();updateSavedSuppliers()});
$('#allWholesalers').onclick=()=>{savedOnly=false;updateSavedSuppliers()};$('#savedWholesalers').onclick=()=>{savedOnly=true;updateSavedSuppliers()};updateSavedSuppliers();

